// Limit / performance checks with large inputs. Run after `npm run build`.
// Inputs are generated by scripts/make-samples.mjs --stress (5K, 6K, 62 s clips).
import { chromium } from "playwright";
import { execFileSync } from "node:child_process";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { serve } from "../../scripts/serve-out.mjs";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../..");
const dir = path.join(root, "samples", "stress");
const PORT = 4323;
let failures = 0;
const check = (name, ok, info = "") => {
  if (!ok) failures++;
  console.log(`${ok ? "PASS" : "FAIL"}  ${name}${info ? "  — " + info : ""}`);
};

const server = await serve(PORT);
const browser = await chromium.launch({ channel: "chrome" });
const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 }, acceptDownloads: true });
await ctx.addInitScript(() => localStorage.setItem("lang", "en"));
const page = await ctx.newPage();

async function open(file) {
  await page.goto(`http://127.0.0.1:${PORT}/`);
  await page.setInputFiles('[data-testid="file-input"]', path.join(dir, file));
  return Promise.race([
    page.waitForSelector('[data-testid="source-info"]', { timeout: 60000 }).then(() => "editor"),
    page.waitForSelector('main [role="alert"]', { timeout: 60000 }).then((e) => e.textContent()),
  ]);
}
async function setInput(sel, v) {
  await page.fill(sel, String(v));
  await page.press(sel, "Enter");
}
async function timedExport(label) {
  const t0 = Date.now();
  await page.getByRole("button", { name: label, exact: true }).click();
  await page.waitForSelector('[data-testid="result-preview"]', { timeout: 600000 });
  const secs = (Date.now() - t0) / 1000;
  const info = (await page.textContent('[data-testid="result-info"]')).replace(/\s+/g, " ");
  const [dl] = await Promise.all([page.waitForEvent("download"), page.click('[data-testid="download"]')]);
  const file = path.join(root, "test-results", "stress-" + dl.suggestedFilename());
  await dl.saveAs(file);
  const dur = execFileSync("ffprobe", ["-v", "error", "-show_entries", "format=duration", "-of", "csv=p=0", file]).toString().trim();
  return { secs, info, dur };
}

try {
  check("5K (5120×2880) opens", (await open("5k.mp4")) === "editor");
  await page.getByRole("radio", { name: "HD" }).click();
  let r = await timedExport("Export GIF");
  check("5K → 1280 px GIF, 5 s", Math.abs(+r.dur - 5) < 0.05, `${r.secs.toFixed(1)} s wall, ${r.info}`);
  await page.getByRole("button", { name: "Back to editing" }).click();
  await page.getByRole("radio", { name: "Silent MP4" }).click();
  await setInput("#out-width", 1920);
  r = await timedExport("Export MP4");
  check("5K → 1920 px MP4, 5 s", Math.abs(+r.dur - 5) < 0.05, `${r.secs.toFixed(1)} s wall, ${r.info}`);

  const six = await open("6k.mp4");
  check("6K (6144×3456) rejected before processing", /exceeds the local limits/.test(six), six);

  check("62 s clip opens", (await open("long-62s.mp4")) === "editor");
  const warn = await page.textContent("aside");
  const disabled = await page.getByRole("button", { name: "Export GIF", exact: true }).isDisabled();
  check("62 s GIF blocked with explanation before encoding", disabled && /exceeds the GIF limit/.test(warn));
  await setInput("#clip-end", "60");
  r = await timedExport("Export GIF");
  check("60 s 960 px 15 fps GIF completes", Math.abs(+r.dur - 60) < 0.05, `${r.secs.toFixed(1)} s wall, ${r.info}`);
  await page.getByRole("button", { name: "Back to editing" }).click();
  await setInput("#clip-end", "62");
  await page.getByRole("radio", { name: "Silent MP4" }).click();
  r = await timedExport("Export MP4");
  check("62 s MP4 completes", Math.abs(+r.dur - 62) < 0.05, `${r.secs.toFixed(1)} s wall, ${r.info}`);
} catch (e) {
  check("stress run completed", false, e.stack);
} finally {
  await browser.close();
  server.close();
}
process.exit(failures ? 1 : 0);
